    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.strictEqual(result.ok, true);
